def evaluate_static_vs_hybrid(tx, rule_hit, ml_score):
    if rule_hit == 'SANCTIONS_MATCH':
        return 'HARD_BLOCK'
    if ml_score >= 850:
        return 'HARD_BLOCK'
    return 'STEP_UP_3DS' if ml_score >= 550 else 'APPROVE'

def update_velocity_buckets(buckets, now_ts, amount):
    # 1-minute sub-buckets pruned beyond 24h
    minute_key = int(now_ts // 60)
    buckets[minute_key] = buckets.get(minute_key, 0.0) + amount
    cutoff = minute_key - 1440
    return {k: v for k, v in buckets.items() if k >= cutoff}

def compute_2hop_ring_risk(graph_client, device_id, timeout_ms=8):
    try:
        neighbors = graph_client.query_2hop(device_id, max_nodes=200, timeout_ms=timeout_ms)
        bad_cards = sum(1 for n in neighbors if n['has_chargeback'])
        return {'ring_size': len(neighbors), 'bad_linked_cards': bad_cards}
    except GraphTimeoutError:
        return {'ring_size': -1, 'bad_linked_cards': 0}

def expected_cost_decision(p_fraud, amount, chargeback_fee=25.0, ltv_loss_ratio=0.15):
    fraud_cost = p_fraud * (amount + chargeback_fee)
    decline_cost = (1.0 - p_fraud) * (amount * ltv_loss_ratio)
    if fraud_cost > decline_cost * 1.5:
        return 'HARD_BLOCK'
    return 'STEP_UP_3DS' if fraud_cost > decline_cost * 0.7 else 'APPROVE'

def is_label_mature(tx_ts, has_chargeback, has_analyst_review, now_ts):
    if has_chargeback or has_analyst_review:
        return True
    return (now_ts - tx_ts) >= (45 * 86400)  # Mature negative

def detect_attack_pivot(stepup_fail_rate, graph_density_zscore):
    if stepup_fail_rate > 0.45 or graph_density_zscore > 3.5:
        alert_fraud_ops('CoordinatedAttackPivot')
        return True
    return False
